  "code": "# 查询永辉超市融资融券相关数据：尝试直接取“今日”关键字段 + 近20个交易日序列
from concurrent.futures import ThreadPoolExecutor

start_20d = "20260401"  # 提前取足够区间，覆盖近20个交易日
end_today  = "20260509"


def q1():
    # 今日两融关键指标（若指标名不匹配，后续再根据相似指标调整）
    return ("today_margin", FinDatabase('股票','永辉超市','融资买入额，融资偿还额，融资净买入额，融券卖出量，融券偿还量，融券净卖出量', '20260509','20260509'))

def q2():
    # 近一段时间序列，便于对比（至少20个交易日）
    return ("seq_margin", FinDatabase('股票','永辉超市','融资买入额，融资偿还额，融资净买入额，融券卖出量，融券偿还量，融券净卖出量', start_20d, end_today))

results = {}
with ThreadPoolExecutor(max_workers=2) as ex:
    for k, v in ex.map(lambda f: f(), [q1, q2]):
        results[k] = v

df_today = results.get('today_margin')
df_seq = results.get('seq_margin')

(df_today is None, df_seq is None, None if df_seq is None else df_seq.shape)"
}
